#!/usr/bin/env python3
"""Regenerate the engine-haxe/data Unicode tables from pinned upstream files.

The 12 *-ranges.txt tables and the hyph-en-us.tex verbatim asset are build
inputs read by Haxe compile-time macros. This program rebuilds each file from
its pinned upstream source and verifies the source SHA-256 before parsing.

Usage:
    python3 tools/unicode-ranges/generate_unicode_ranges.py --source-dir DIR
    python3 tools/unicode-ranges/generate_unicode_ranges.py --source-dir DIR --check

--check compares the generated bytes with the files in the output directory
without writing; it exits 1 when any file differs or is missing.

The input directory must hold the seven files named by the PinnedSource
constants below. The download commands are documented in docs/unicode-data.md.
"""

from __future__ import annotations

import argparse
import hashlib
import sys
from dataclasses import dataclass
from pathlib import Path


REPO_ROOT = Path(__file__).resolve().parents[2]
DEFAULT_OUTPUT_DIR = REPO_ROOT / "engine-haxe" / "data"
UNICODE_VERSION = "17.0.0"


@dataclass(frozen=True)
class PinnedSource:
    filename: str
    url: str
    sha256: str


EMOJI_DATA = PinnedSource(
    "emoji-data.txt",
    f"https://www.unicode.org/Public/{UNICODE_VERSION}/ucd/emoji/emoji-data.txt",
    "2cb2bb9455cda83e8481541ecf5b6dfda66a3bb89efa3fa7c5297eccf607b72b",
)
EMOJI_VARIATION_SEQUENCES = PinnedSource(
    "emoji-variation-sequences.txt",
    f"https://www.unicode.org/Public/{UNICODE_VERSION}/ucd/emoji/"
    "emoji-variation-sequences.txt",
    "bb3d09ef03f206012c7532dd52dc0a21c9efddba0135ea4cf0d9201b8b9bba7e",
)
DERIVED_GENERAL_CATEGORY = PinnedSource(
    "DerivedGeneralCategory.txt",
    f"https://www.unicode.org/Public/{UNICODE_VERSION}/ucd/extracted/"
    "DerivedGeneralCategory.txt",
    "d62e5bab70ca74f099343f71224fa051cb1fdd61a1ab45c0488c44cfc0b6102e",
)
LINE_BREAK = PinnedSource(
    "LineBreak.txt",
    f"https://www.unicode.org/Public/{UNICODE_VERSION}/ucd/LineBreak.txt",
    "e6a18fa91f8f6a6f8e534b1d3f128c21ada45bfe152eb6b1bcc5e15fd8ac92e6",
)
SCRIPTS = PinnedSource(
    "Scripts.txt",
    f"https://www.unicode.org/Public/{UNICODE_VERSION}/ucd/Scripts.txt",
    "9f5e50d3abaee7d6ce09480f325c706f485ae3240912527e651954d2d6b035bf",
)
EAST_ASIAN_SPACING = PinnedSource(
    "east-asian-spacing.txt",
    "https://www.unicode.org/reports/tr59/east-asian-spacing.txt",
    "49fe340a964a6e8e0ebc30099709c665cc6138d444b5c36dc336604047f1010f",
)
HYPH_EN_US = PinnedSource(
    "hyph-en-us.tex",
    "https://raw.githubusercontent.com/hyphenation/tex-hyphen/"
    "dce23b4eb2df218ec6893b851562316d7cf37355/hyph-utf8/tex/generic/"
    "hyph-utf8/patterns/tex/hyph-en-us.tex",
    "f4ffcd96c5cbc886bdad23f95dcae8edc3cd3620eae62f7946eceda97c4e68f8",
)

# LineBreak class names consumed by UnicodePunctuationLineBreak. The value is
# the enum index written to the table's third column.
PUNCTUATION_CLASS_IDS = {
    "BA": 0,
    "B2": 1,
    "CL": 2,
    "CP": 3,
    "EX": 4,
    "HH": 5,
    "HY": 6,
    "IN": 7,
    "IS": 8,
    "NS": 9,
    "OP": 10,
    "QU": 11,
    "SY": 12,
}

NEUTRAL_SCRIPTS = {"Common", "Inherited", "Unknown"}
EAST_ASIAN_SCRIPTS = {"Bopomofo", "Han", "Hangul", "Hiragana", "Katakana"}

# East_Asian_Spacing class to table value; O is the @missing default and is
# omitted from the table.
EAST_ASIAN_SPACING_VALUES = {"W": 0, "N": 1, "C": 3}


def read_pinned(source: PinnedSource, source_dir: Path) -> bytes:
    path = source_dir / source.filename
    if not path.is_file():
        raise SystemExit(f"missing pinned source: {path}")
    data = path.read_bytes()
    actual = hashlib.sha256(data).hexdigest()
    if actual != source.sha256:
        raise SystemExit(
            f"unexpected SHA-256 for {path}: {actual} (expected {source.sha256})"
        )
    return data


def parse_range(field: str) -> tuple[int, int]:
    if ".." in field:
        start, end = field.split("..", 1)
        return int(start, 16), int(end, 16)
    value = int(field, 16)
    return value, value


def property_records(data: bytes):
    for line in data.decode("utf-8").splitlines():
        content = line.split("#", 1)[0].strip()
        if not content:
            continue
        parts = [part.strip() for part in content.split(";")]
        yield parse_range(parts[0]), parts[1:]


def coalesce_pairs(ranges: list[tuple[int, int]]) -> list[tuple[int, int]]:
    result: list[tuple[int, int]] = []
    for start, end in sorted(ranges):
        if result and start <= result[-1][1] + 1:
            result[-1] = (result[-1][0], max(result[-1][1], end))
        else:
            result.append((start, end))
    return result


def merge_triples(
    records: list[tuple[int, int, int]]
) -> list[tuple[int, int, int]]:
    result: list[tuple[int, int, int]] = []
    for start, end, value in sorted(records):
        if result and result[-1][2] == value and result[-1][1] + 1 == start:
            result[-1] = (result[-1][0], end, value)
        else:
            result.append((start, end, value))
    return result


def pairs_header(
    provenance: str, source: PinnedSource, records: int, elements: int
) -> list[str]:
    return [
        f"# Provenance: {provenance}",
        f"# Source: {source.url}",
        f"# SHA-256: {source.sha256}",
        f"# Records: {records} pairs ({elements} elements)",
    ]


def triples_header(
    provenance: str, source: PinnedSource, records: int, elements: int
) -> list[str]:
    return [
        f"# Provenance: {provenance}",
        f"# Source: {source.url}",
        f"# SHA-256: {source.sha256}",
        f"# Records: {records} triples ({elements} elements)",
    ]


def render_pairs(header: list[str], ranges: list[tuple[int, int]]) -> str:
    body = "\n".join(f"{start:06X} {end:06X}" for start, end in ranges)
    return "\n".join(header) + "\n" + body + "\n"


def render_triples(header: list[str], records: list[tuple[int, int, int]]) -> str:
    body = "\n".join(
        f"{start:06X} {end:06X} {value:X}" for start, end, value in records
    )
    return "\n".join(header) + "\n" + body + "\n"


def generate_emoji_tables(source_dir: Path) -> dict[str, str]:
    records = list(property_records(read_pinned(EMOJI_DATA, source_dir)))
    tables: dict[str, str] = {}
    for property_name, filename in (
        ("Emoji_Presentation", "emoji-presentation-ranges.txt"),
        ("Emoji", "emoji-ranges.txt"),
        ("Emoji_Modifier_Base", "emoji-modifier-base-ranges.txt"),
        ("Extended_Pictographic", "extended-pictographic-ranges.txt"),
    ):
        ranges = coalesce_pairs(
            [record for record, fields in records if fields[0] == property_name]
        )
        header = pairs_header(
            f"Unicode {UNICODE_VERSION} emoji-data.txt",
            EMOJI_DATA,
            len(ranges),
            len(ranges) * 2,
        )
        tables[filename] = render_pairs(header, ranges)
    return tables


def emoji_style_bases(data: bytes):
    for line in data.decode("utf-8").splitlines():
        content = line.split("#", 1)[0].strip()
        if not content:
            continue
        code_points, description = [part.strip() for part in content.split(";", 1)]
        if not description.startswith("emoji style"):
            continue
        sequence = [int(code_point, 16) for code_point in code_points.split()]
        if len(sequence) != 2 or sequence[1] != 0xFE0F:
            raise SystemExit(f"unexpected emoji style sequence: {code_points}")
        yield sequence[0]


def generate_emoji_style_variation_table(source_dir: Path) -> str:
    data = read_pinned(EMOJI_VARIATION_SEQUENCES, source_dir)
    bases = [(base, base) for base in emoji_style_bases(data)]
    ranges = coalesce_pairs(bases)
    header = pairs_header(
        f"Unicode {UNICODE_VERSION} emoji-variation-sequences.txt",
        EMOJI_VARIATION_SEQUENCES,
        len(ranges),
        len(ranges) * 2,
    )
    return render_pairs(header, ranges)


def generate_derived_general_category_tables(
    source_dir: Path,
) -> dict[str, str]:
    records = list(property_records(read_pinned(DERIVED_GENERAL_CATEGORY, source_dir)))
    tables: dict[str, str] = {}
    for prefixes, filename in (
        (("L", "M", "N"), "unicode-word-character-ranges.txt"),
        (("M",), "unicode-combining-mark-ranges.txt"),
        (("N",), "unicode-number-ranges.txt"),
        (("S",), "unicode-symbol-ranges.txt"),
    ):
        ranges = coalesce_pairs(
            [record for record, fields in records if fields[0].startswith(prefixes)]
        )
        elements = len(ranges) * 2
        if filename == "unicode-symbol-ranges.txt":
            # The committed header of this table reports the number of code
            # points covered by the ranges (8617), not the array element count
            # (484). Preserve the committed header so the file stays
            # byte-identical; see docs/unicode-data.md.
            elements = sum(end - start + 1 for start, end in ranges)
        header = pairs_header(
            f"Unicode {UNICODE_VERSION} DerivedGeneralCategory.txt",
            DERIVED_GENERAL_CATEGORY,
            len(ranges),
            elements,
        )
        tables[filename] = render_pairs(header, ranges)
    return tables


def generate_punctuation_table(source_dir: Path) -> str:
    records: list[tuple[int, int, int]] = []
    for (start, end), fields in property_records(read_pinned(LINE_BREAK, source_dir)):
        class_id = PUNCTUATION_CLASS_IDS.get(fields[0])
        if class_id is None:
            continue
        records.append((start, end, class_id))
    merged = merge_triples(records)
    header = triples_header(
        f"Unicode {UNICODE_VERSION} LineBreak.txt",
        LINE_BREAK,
        len(merged),
        len(merged) * 3,
    )
    header += [
        "# All three columns are hexadecimal; the class column indexes",
        "# UnicodePunctuationLineBreakClass constructors.",
    ]
    return render_triples(header, merged)


def generate_script_table(source_dir: Path) -> str:
    records: list[tuple[int, int, int]] = []
    for record, fields in property_records(read_pinned(SCRIPTS, source_dir)):
        script = fields[0]
        if script in NEUTRAL_SCRIPTS:
            continue
        group = 1 if script in EAST_ASIAN_SCRIPTS else 2
        records.append((record[0], record[1], group))
    merged = merge_triples(records)
    header = triples_header(
        f"Unicode {UNICODE_VERSION} Scripts.txt",
        SCRIPTS,
        len(merged),
        len(merged) * 3,
    )
    return render_triples(header, merged)


def generate_east_asian_spacing_table(source_dir: Path) -> str:
    records: list[tuple[int, int, int]] = []
    for record, fields in property_records(
        read_pinned(EAST_ASIAN_SPACING, source_dir)
    ):
        value = EAST_ASIAN_SPACING_VALUES.get(fields[0])
        if value is None:
            continue
        records.append((record[0], record[1], value))
    merged = merge_triples(records)
    header = [
        "# Provenance: Unicode Proposed Draft UTR #59 east-asian-spacing.txt",
        "# Source date: 2024-12-16",
        f"# Source: {EAST_ASIAN_SPACING.url}",
        f"# SHA-256: {EAST_ASIAN_SPACING.sha256}",
        f"# Records: {len(merged)} triples ({len(merged) * 3} elements)",
    ]
    return render_triples(header, merged)


def collect_tables(source_dir: Path) -> dict[str, bytes]:
    tables: dict[str, str] = {}
    tables.update(generate_emoji_tables(source_dir))
    tables["emoji-style-variation-ranges.txt"] = (
        generate_emoji_style_variation_table(source_dir)
    )
    tables.update(generate_derived_general_category_tables(source_dir))
    tables["punctuation-line-break-ranges.txt"] = generate_punctuation_table(source_dir)
    tables["unicode-script-evidence-ranges.txt"] = generate_script_table(source_dir)
    tables["east-asian-spacing-ranges.txt"] = generate_east_asian_spacing_table(
        source_dir
    )
    result = {name: text.encode("utf-8") for name, text in tables.items()}
    # The hyphenation pattern file is copied without parsing; the pinned
    # SHA-256 is checked by read_pinned before it reaches the output.
    result["hyph-en-us.tex"] = read_pinned(HYPH_EN_US, source_dir)
    return result


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--source-dir",
        type=Path,
        required=True,
        help="directory holding the seven pinned upstream files",
    )
    parser.add_argument(
        "--output-dir",
        type=Path,
        default=DEFAULT_OUTPUT_DIR,
        help=f"table output directory (default: {DEFAULT_OUTPUT_DIR})",
    )
    parser.add_argument(
        "--check",
        action="store_true",
        help="compare with the output directory instead of writing files",
    )
    args = parser.parse_args()

    tables = collect_tables(args.source_dir)
    failures = 0
    for filename in sorted(tables):
        target = args.output_dir / filename
        if args.check:
            if not target.is_file():
                print(f"missing  {filename}")
                failures += 1
                continue
            if target.read_bytes() == tables[filename]:
                print(f"identical {filename}")
            else:
                print(f"mismatch  {filename}")
                failures += 1
        else:
            if target.is_file() and target.read_bytes() == tables[filename]:
                print(f"unchanged {filename}")
            else:
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_bytes(tables[filename])
                print(f"wrote     {filename}")

    if args.check:
        print(f"{len(tables) - failures}/{len(tables)} files match")
        return 1 if failures else 0
    return 0


if __name__ == "__main__":
    sys.exit(main())
